// Writes how-things-work/INDEX.md: every reel in posting order. No dependencies.
//   node tools/index.mjs
import fs from "node:fs";
import path from "node:path";
import { parse } from "./miniyaml.mjs";
import { contentDir, validateAll } from "./validate.mjs";

const { reels, errors } = validateAll(parse);
const counts = {};
for (const r of reels) counts[r.series] = (counts[r.series] ?? 0) + 1;
const esc = (s) => String(s ?? "").replace(/\|/g, "\\|");
const lines = [
  "# Every reel, in posting order",
  "",
  "`npm run daily` renders these top to bottom (2 a day by default). Generated by `video/tools/index.mjs`; don't edit by hand.",
  "",
  `${reels.length} reels: ` + Object.entries(counts).map(([s, n]) => `${s} ${n}`).join(", ") + ".",
  "",
  "| # | Series | Topic | Title | Length |",
  "| --- | --- | --- | --- | --- |",
  ...reels.map(
    (r) =>
      `| [${r.id}](${r.series}/${r.id}.md) | ${r.series} | ${esc(r.topic)} | ${esc(r.title)} | ${r.duration}s |`,
  ),
];
if (errors.length) lines.push("", `${errors.length} script(s) currently fail the checker and are not listed.`);
fs.writeFileSync(path.join(contentDir, "INDEX.md"), lines.join("\n") + "\n");
console.log(`Wrote how-things-work/INDEX.md (${reels.length} reels${errors.length ? `, ${errors.length} with errors` : ""}).`);
